function isJsonWhitespaceOnly(text) {
  return /^[\u0009\u000D\u0020]*$/.test(text);
}

async function scanBundle(input, deliver) {
  let count = 0;
  let line = 1;
  let parts = [];

  async function handleLine(text, endedByLf) {
    const currentLine = line++;

    if (
      endedByLf &&
      text.length > 0 &&
      text.charCodeAt(text.length - 1) === 13
    ) {
      text = text.slice(0, -1);
    }

    if (isJsonWhitespaceOnly(text)) {
      return true;
    }

    let value;
    try {
      value = JSON.parse(text);
    } catch {
      const error = new Error("Invalid JSON on line " + currentLine);
      error.code = "BAD_LINE";
      error.line = currentLine;
      throw error;
    }

    count += 1;
    return (await deliver(value, currentLine)) !== false;
  }

  async function processText(text) {
    let start = 0;

    for (let index = 0; index < text.length; index += 1) {
      if (text.charCodeAt(index) !== 10) {
        continue;
      }

      if (index > start) {
        parts.push(text.slice(start, index));
      }

      const current = parts.join("");
      parts = [];

      if (!(await handleLine(current, true))) {
        return false;
      }

      start = index + 1;
    }

    if (start < text.length) {
      parts.push(text.slice(start));
    }

    return true;
  }

  try {
    const decoder = new TextDecoder("utf-8", { fatal: true });

    while (true) {
      const chunk = await input.read();

      if (chunk === null) {
        const remainder = decoder.decode();

        if (!(await processText(remainder))) {
          return count;
        }

        if (parts.length > 0) {
          const finalLine = parts.join("");
          parts = [];

          if (!(await handleLine(finalLine, false))) {
            return count;
          }
        }

        return count;
      }

      const text = decoder.decode(chunk, { stream: true });

      if (!(await processText(text))) {
        return count;
      }
    }
  } finally {
    await input.close();
  }
}
